          const simples = (['fase_msg', 'so_tag'].includes(o.acao) || cpfVerificado) && !(o.atalhos && o.atalhos.length) && !o.atalho && !(o.trocas && o.trocas.length) && !o.soSeNossaUltima && !o.exige && !o.pularSe && !o.fechar && !o.forcar && !o.reenvio;
