          if (simples && !tagsOk && txt && !/undefined/.test(txt) && bmApiLigada()) { await bmEnviarTexto(o.hash, txt); salvaProgresso({ msgFeita: 1, linhaFeita: 1 }); passos.push('msg: pela API (8.58) — tag pela tela'); }
