        try { diario(alvo.nomeReal || alvo.nome || alvo.hash.slice(0, 5), '⭐ assinado — toque ' + (n + 1) + ' do ' + (fe.fase === 'falta desbloquear' ? 'desbloqueio' : 'Meu INSS (anuência)')); } catch (e) {}
